{"description":"Prepare stdin files and run harness for all tests","cmd":": > /tmp/empty.stdin
printf '(+ 7 8)\n' > /tmp/cal.stdin
printf '(hello world)\n' > /tmp/read.stdin
printf '5\n7\n+\n' > /tmp/io.stdin

cd /app
for t in test/*.scm; do
  f=$(basename "$t")
  case "$f" in
    calculator.scm) s=/tmp/cal.stdin;;
    test_read.scm) s=/tmp/read.stdin;;
    06-interactive-io.scm) s=/tmp/io.stdin;;
    *) s=/tmp/empty.stdin;;
  esac
  /tmp/harness.sh "$f" "$s"
done"}

{"description":"Catch exception and print traceback","cmd":"cd /app && cat > /tmp/trace2.py <<'EOF'
import sys, traceback
sys.path.insert(0, '/app')
import interp
sys.setrecursionlimit(3000)
class E(Exception): pass
orig = interp.eval_expr
def tracked(expr, env):
    try:
        return orig(expr, env)
    except RecursionError:
        raise
# emulate stdin
import io
sys.stdin = io.StringIO("eval.scm\ntest/01-factorial.scm\n")
try:
    interp.run_file("eval.scm")
except Exception:
    traceback.print_exc()
EOF
timeout 20 python3 /tmp/trace2.py 2>&1 | tail -60"}

{"description":"Full harness2 run with timeouts to classify self-interpretation results","cmd":"cd /app
for t in test/*.scm; do
  f=$(basename "$t")
  case "$f" in
    calculator.scm) s=/tmp/cal.stdin;;
    test_read.scm) s=/tmp/read.stdin;;
    06-interactive-io.scm) s=/tmp/io.stdin;;
    *) s=/tmp/empty.stdin;;
  esac
  echo -n "$f: "
  printf 'eval.scm\ntest/%s\n' "$f" > /tmp/in
  cat "$s" >> /tmp/in
  out=$(timeout 12 python3 interp.py eval.scm < /tmp/in 2>&1)
  code=$?
  if [ $code -ne 0 ]; then echo "TIMEOUT/ERR($code)"; elif echo "$out" | grep -q "RECURSION\|Error"; then echo "FAIL"; else echo "OK"; fi
done"}
